async def act(page):
    """
    Reduce the product's main price by 10% on the current Magento product edit page.

    Steps:
    - Open the "Prices" tab via the left navigation link.
    - Locate the main Price input using accessibility-role-based selectors only (get_by_role).
      Try a few role/name combinations and fall back to scanning textboxes for a numeric value.
    - Read current value, compute a 10% reduction, and set the new value (2 decimal places).
    - Click the Save button (use accessibility selector). Save is the last action.
    """
    import re
    import asyncio

    # Knowledge base functions: none are available/importable from the provided knowledge base.
    # Therefore, we will interact directly with the page via Playwright APIs.

    # 1) Open the Prices tab
    prices_link = page.get_by_role("link", name="Prices")
    if await prices_link.count() == 0:
        # If Prices link is not found, raise a clear error
        raise Exception("Prices link not found in the left navigation")
    await prices_link.click()
    # wait for the tab content to load
    await page.wait_for_load_state("networkidle")

    # 2) Try to find the main Price field using accessibility-role-centric selectors only
    price_locator = page.get_by_role("textbox", name="Price")
    if await price_locator.count() == 0:
        price_locator = page.get_by_role("spinbutton", name="Price")

    # 3) Fallback: scan all textboxes for a numeric value that looks like a price
    if await price_locator.count() == 0:
        all_textboxes = page.get_by_role("textbox")
        tb_count = await all_textboxes.count()
        candidate = None
        for i in range(tb_count):
            tb = all_textboxes.nth(i)
            # try to safely get a value - some textboxes may be empty or not relevant
            try:
                val = await tb.input_value()
            except Exception:
                val = ""
            # consider as candidate if it contains digits and optionally a decimal point
            if val and re.search(r"\d", val):
                # prefer values that look like monetary amounts (contain a dot or are >1)
                cleaned = re.sub(r"[^0-9.-]", "", val)
                try:
                    num = float(cleaned)
                except Exception:
                    continue
                # Heuristic: price usually > 0
                if num >= 0:
                    candidate = tb
                    break
        if candidate is None:
            raise Exception("Could not find a Price input using accessibility selectors")
        price_locator = candidate

    # Use the first matching element
    price_el = price_locator.first()

    # 4) Read current value
    current_value_raw = await price_el.input_value()
    cleaned = re.sub(r"[^0-9.-]", "", current_value_raw)
    if cleaned == "":
        raise Exception(f"Price input contained no numeric value (raw: '{current_value_raw}')")

    try:
        current_price = float(cleaned)
    except Exception as e:
        raise Exception(f"Failed to parse current price '{current_value_raw}': {e}")

    # 5) Compute new price = current_price * 0.9 (10% reduction), keep 2 decimal places
    new_price = round(current_price * 0.9, 2)

    # 6) Fill the new price back into the field
    await price_el.fill(str(new_price))

    # 7) Save the product changes using the Save button (accessibility selector)
    save_button = page.get_by_role("button", name="Save")
    if await save_button.count() == 0:
        raise Exception('Save button not found')
    await save_button.click()

    # Wait for the save to complete
    await page.wait_for_load_state("networkidle")

    # Print the new price so the harness can observe the result
    print(str(new_price))

